<script setup>
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue'; import Avatar from '../components/Avatar.vue'; import Modal from '../components/Modal.vue'; import EventTable from '../components/EventTable.vue';
import { data, employees, events, presence, canControl, user } from '../store.js';
import { idEqual } from '../domain.js'; import { time, duration } from '../format.js';
const emit = defineEmits(['navigate']);
const query = ref(''), floor = ref(''), status = ref(''), selected = ref(null);
const occupants = id => employees.value.filter(e => idEqual(presence.value.get(String(e.id))?.roomId, id));
const rooms = computed(() => data.rooms.filter(r => (!query.value || `${r.name} ${r.number}`.toLowerCase().includes(query.value.toLowerCase())) && (!floor.value || String(r.floor) === floor.value) && (!status.value || (status.value === 'occupied' ? occupants(r.id).length > 0 : occupants(r.id).length === 0))));
const floors = computed(() => [...new Set(data.rooms.map(r => r.floor))].sort((a, b) => a - b));
</script>
<template><div class="page-header"><div><span class="eyebrow">ПРИСУТСТВИЕ В ОРГАНИЗАЦИИ</span><h1>Занятость помещений<span class="heading-dot">.</span></h1><p>{{ user.role === 'manager' ? 'Присутствие сотрудников вашего подразделения.' : 'Помещения, сотрудники и время их пребывания.' }}</p></div><span class="badge green"><span class="dot"></span>{{ presence.size }} сотрудников в помещениях</span></div><div class="toolbar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" placeholder="Найти помещение…" aria-label="Найти помещение" /></label><select v-model="floor" aria-label="Фильтр по этажу"><option value="">Все этажи</option><option v-for="item in floors" :key="item" :value="String(item)">{{ item }} этаж</option></select><select v-model="status" aria-label="Фильтр занятости"><option value="">Любая занятость</option><option value="occupied">Занятые</option><option value="free">Свободные</option></select><span class="toolbar-count">Найдено: {{ rooms.length }}</span></div><div v-if="!rooms.length" class="panel empty-state"><Icon name="rooms" :size="36" /><h3>Помещения не найдены</h3><p>Измените фильтры или добавьте помещение.</p></div><div v-else class="room-grid"><article v-for="room in rooms" :key="room.id" class="room-card"><div class="room-card-heading"><span class="room-symbol" :class="{ occupied: occupants(room.id).length }"><Icon :name="room.zone === 'Ограниченный доступ' ? 'lock' : 'rooms'" :size="24" /></span><span class="badge" :class="occupants(room.id).length ? 'green' : 'neutral'"><span class="dot"></span>{{ occupants(room.id).length ? 'Занято' : 'Свободно' }}</span></div><button class="room-title" @click="selected = room">{{ room.name }}<Icon name="right" :size="18" /></button><p class="room-location"><Icon name="pin" :size="14" />{{ room.floor }} этаж · Кабинет {{ room.number }}</p><div class="capacity-row"><span>Вместимость</span><strong>{{ occupants(room.id).length }} <span>/ {{ room.capacity }} чел.</span></strong></div><div class="capacity-track"><span :style="{ width: `${Math.min(100, occupants(room.id).length / Math.max(1, room.capacity) * 100)}%` }"></span></div><div class="room-people"><template v-if="occupants(room.id).length"><div v-for="person in occupants(room.id).slice(0, 3)" :key="person.id" class="room-person"><Avatar :person="person" size="xs" /><strong>{{ person.fullName }}</strong><span>с {{ time(presence.get(String(person.id)).since) }}</span></div><button v-if="occupants(room.id).length > 3" class="text-button" @click="selected = room">Ещё {{ occupants(room.id).length - 3 }} сотрудников</button></template><div v-else class="no-occupants"><Icon name="users" :size="20" /><span>Сейчас никого нет</span></div></div><button class="room-card-footer" @click="selected = room"><span>{{ room.zone }}</span>Подробнее <Icon name="arrow" :size="15" /></button></article></div><div class="subtle-note"><Icon name="help" :size="17" /><p>Занятость рассчитана по входам и выходам. При отсутствии событий местоположение сотрудника неизвестно.</p></div><Modal v-if="selected" :title="selected.name" wide @close="selected = null"><div class="room-detail-meta"><span><Icon name="pin" :size="16" />{{ selected.floor }} этаж · {{ selected.number }}</span><span>{{ selected.purpose }}</span></div><h3 class="section-heading">Сейчас в помещении <span class="counter">{{ occupants(selected.id).length }}</span></h3><div v-if="!occupants(selected.id).length" class="empty-state small"><Icon name="users" :size="30" /><p>Зарегистрированных посетителей нет.</p></div><div v-for="person in occupants(selected.id)" :key="person.id" class="occupant-detail"><Avatar :person="person" /><div><strong>{{ person.fullName }}</strong><small>Вход в {{ time(presence.get(String(person.id)).since) }}</small></div><span class="badge neutral"><Icon name="clock" :size="13" />{{ duration(presence.get(String(person.id)).since) }}</span></div><h3 class="section-heading">Последние события</h3><EventTable :items="events.filter(e => idEqual(e.roomId, selected.id)).slice().sort((a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp)).slice(0, 5)" compact /><div v-if="canControl" class="form-actions"><button class="button primary" @click="selected = null; emit('navigate', 'control')"><Icon name="scan" :size="17" />Открыть точку контроля</button></div></Modal></template>
